		{"af_bella,af_sky", []string{"af_bella", "af_sky"}, []float32{0.5, 0.5}},
		{" af_bella , af_sky ", []string{"af_bella", "af_sky"}, []float32{0.5, 0.5}},
		{"af_bella:3,af_sky:1", []string{"af_bella", "af_sky"}, []float32{0.75, 0.25}},
