		"af_bella,,af_sky",        // and so is a doubled one
		"af_bella:0.7,af_sky",     // half-weighted: two readings, so neither
		"af_bella:x,af_sky:1",     // not a number
		"af_bella:-1,af_sky:2",    // negative
